      "keystrokes": "cat > scripts/openseti.py << 'ENDSCRIPT'
#!/usr/bin/env python3
import argparse
import json
from pathlib import Path

def analyze_signal(data):
    score = 0.0
    reasons = []
    bandwidth = data.get("bandwidth_hz", 100)
    if bandwidth < 10:
        score += 0.35
        reasons.append("Narrowband signal detected (" + str(bandwidth) + " Hz)")
    drift = data.get("doppler_drift_hz_s", 0)
    if abs(drift) > 0.1:
        score += 0.25
        reasons.append("Doppler drift detected (" + str(drift) + " Hz/s)")
    snr = data.get("snr", 0)
    if snr > 10:
        score += 0.25
        reasons.append("High SNR detected (" + str(snr) + ")")
    if snr > 15:
        score += 0.15
        reasons.append("Very high SNR suggests strong signal")
    score = min(score, 1.0)
    if score >= 0.7:
        classification = "ANOMALY_FLAGGED"
    elif score >= 0.4:
        classification = "INVESTIGATING"
    elif score >= 0.15:
        classification = "WEAK_SIGNAL"
    else:
        classification = "NATURAL"
    return classification, score, reasons

def run_scan(input_file="scan_input.json"):
    input_path = Path(input_file)
    if not input_path.exists():
        print("Error: Input file not found")
        return None
    with open(input_path, "r") as f:
        data = json.load(f)
    classification, score, reasons = analyze_signal(data)
    result = {
        "observation_id": data.get("observation_id", "unknown"),
        "classification": classification,
        "score": round(score, 2),
        "justification": "; ".join(reasons) if reasons else "No anomalies",
        "marker_token": data.get("marker_token", "none")
    }
    return result

def main():
    parser = argparse.ArgumentParser(description="OpenSETI Scanner")
    subparsers = parser.add_subparsers(dest="command")
    reg = subparsers.add_parser("register")
    reg.add_argument("wallet")
    scan = subparsers.add_parser("scan")
    scan.add_argument("--continuous", action="store_true")
    scan.add_argument("--input", default="scan_input.json")
    args = parser.parse_args()
    if args.command == "register":
        print("Registered: " + args.wallet)
    elif args.command == "scan":
        result = run_scan(args.input)
        if result:
            print(json.dumps(result, indent=2))
        if args.continuous:
            print("[Continuous mode: Scan complete]")
    else:
        parser.print_help()

if __name__ == "__main__":
    main()
ENDSCRIPT\n",
